const int MOD = 998244353;

int addmod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}
int submod(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}
int mulmod(long long a, long long b) {
    return int((a * b) % MOD);
}
int modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return int(r);
}
int invmod(int a) {
    return modpow(a, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int p, s, r;
    if (!(cin >> p >> s >> r)) return 0;

    // dp[k][sum]: number of ways to distribute 'sum' among k players, each >=0
    // and each <= current max (handled per max via prefix sums).
    static int dp[105][5005];
    static int pref[5006];

    int totalStates = 0;
    int winStates = 0;

    for (int mx = r; mx <= s; ++mx) {
        int rem = s - mx;
        if (rem < 0) break;

        // dp initialization
        memset(dp, 0, sizeof(dp));
        dp[0][0] = 1;

        for (int k = 1; k <= p - 1; ++k) {
            pref[0] = dp[k - 1][0];
            for (int sum = 1; sum <= rem; ++sum)
                pref[sum] = addmod(pref[sum - 1], dp[k - 1][sum]);

            for (int sum = 0; sum <= rem; ++sum) {
                int l = sum - mx;
                if (l <= 0) {
                    dp[k][sum] = pref[sum];
                } else {
                    dp[k][sum] = submod(pref[sum], pref[l - 1]);
                }
            }
        }

        int waysAll = dp[p - 1][rem];
        if (!waysAll) continue;

        totalStates = addmod(totalStates, waysAll);

        // count winning states
        int waysWin = 0;
        // Hasan strictly greater
        if (mx > 0) {
            int rem2 = rem;
            // others <= mx-1
            memset(dp, 0, sizeof(dp));
            dp[0][0] = 1;
            for (int k = 1; k <= p - 1; ++k) {
                pref[0] = dp[k - 1][0];
                for (int sum = 1; sum <= rem2; ++sum)
                    pref[sum] = addmod(pref[sum - 1], dp[k - 1][sum]);
                for (int sum = 0; sum <= rem2; ++sum) {
                    int l = sum - (mx - 1);
                    if (l <= 0) dp[k][sum] = pref[sum];
                    else dp[k][sum] = submod(pref[sum], pref[l - 1]);
                }
            }
            waysWin = addmod(waysWin, dp[p - 1][rem2]);
        }

        // Hasan tied with some others at mx
        // Let t = number of players (including Hasan) who have score mx.
        // For each t >=1, Hasan's winning probability contribution is 1/t.
        // We count configurations where exactly t players have mx and others < mx.
        for (int t = 1; t <= p; ++t) {
            // Hasan is one of these t.
            // Choose t-1 other players among p-1: C(p-1, t-1)
            // Remaining p - t players have scores in [0, mx-1].
            int playersLess = p - t;
            int sumLess = rem - (t - 1) * mx;
            if (sumLess < 0) continue;

            memset(dp, 0, sizeof(dp));
            dp[0][0] = 1;
            for (int k = 1; k <= playersLess; ++k) {
                pref[0] = dp[k - 1][0];
                for (int sum = 1; sum <= sumLess; ++sum)
                    pref[sum] = addmod(pref[sum - 1], dp[k - 1][sum]);
                for (int sum = 0; sum <= sumLess; ++sum) {
                    int l = sum - (mx - 1);
                    if (l <= 0) dp[k][sum] = pref[sum];
                    else dp[k][sum] = submod(pref[sum], pref[l - 1]);
                }
            }
            int waysConfig = dp[playersLess][sumLess];
            if (!waysConfig) continue;

            // multiply by combinations C(p-1, t-1)
            static int C[105][105];
            static bool combInit = false;
            if (!combInit) {
                combInit = true;
                for (int i = 0; i <= 100; ++i) {
                    C[i][0] = C[i][i] = 1;
                    for (int j = 1; j < i; ++j)
                        C[i][j] = addmod(C[i - 1][j - 1], C[i - 1][j]);
                }
            }
            int comb = C[p - 1][t - 1];
            int contrib = mulmod(waysConfig, comb);
            int invt = invmod(t);
            contrib = mulmod(contrib, invt);
            waysWin = addmod(waysWin, contrib);
        }

        winStates = addmod(winStates, waysWin);
    }

    if (totalStates == 0) {
        cout << 0 << '\n';
        return 0;
    }

    int ans = mulmod(winStates, invmod(totalStates));
    cout << ans << '\n';
    return 0;
}

