using namespace std;

const int MOD = 998244353;

int addmod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}
int submod(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}
int mulmod(long long a, long long b) {
    return int((a * b) % MOD);
}
int modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return int(r);
