            int ways = 0;

            // Count distributions of rem among p-1 players with max exactly M
            // Inclusion-exclusion on upper bound M
            for (int k = 1; k <= p - 1; ++k) {
                int sign = (k & 1) ? 1 : -1;
                int rem2 = rem - k * (M + 1);
