    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int p, s, r;
    if (!(cin >> p >> s >> r)) return 0;

    // Precompute factorials and inverse factorials up to s + p
    int N = s + p + 5;
    vector<int> fact(N), invfact(N);
    fact[0] = 1;
    for (int i = 1; i < N; ++i) fact[i] = mulmod(fact[i - 1], i);
