    // Let x = a1 - r >= 0, sum others = s - r - x
    // For each x, number of nonnegative solutions for others: C((s - r - x) + p - 2, p - 2)
    int total_states = 0;
    for (int x = 0; x <= s - r; ++x) {
        int rem = s - r - x;
        total_states = addmod(total_states, C(rem + p - 2, p - 2));
    }

    int win_num = 0;

    // Iterate Hasan's actual score a1
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        if (rem < 0) break;

        // For each possible maximum among others M
        for (int M = 0; M <= rem; ++M) {
            int ways_M = 0;

            // Count sequences of p-1 players, sum=rem, max exactly M
            // Using inclusion-exclusion on upper bound M
            // Number of sequences with all <= M and sum=rem:
            // sum_{k} (-1)^k * C(p-1, k) * C(rem - k*(M+1) + p - 2, p - 2)
