                int sign = (k & 1) ? MOD - 1 : 1;
                int rem2 = rem - k * (M + 1);
                int term = mulmod(C(p - 1, k), C(rem2 + p - 2, p - 2));
                if (sign == 1) ways_M = addmod(ways_M, term);
                else ways_M = submod(ways_M, term);
            }

            if (ways_M == 0) continue;

            if (M > a1) {
                // Hasan cannot win
