                // Hasan strictly greater than all others
                win_num = addmod(win_num, ways_M);
            } else {
                // M == a1, Hasan tied with some subset of players
                // Let t = number of players (among others) with score == a1
                // We need expected 1/(t+1) over all such sequences.
                // We compute sum over t: ways_{M,t} * 1/(t+1)
                // ways_{M,t}: sequences with exactly t players at M and others <= M-1
                // Choose t players: C(p-1, t)
                // Remaining p-1-t players sum to rem - t*M, each <= M-1
