const int MOD = 998244353;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int addmod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    if (!(cin >> p >> s >> r)) return 0;

    // Precompute factorials and inverse factorials up to s + p
    int N = s + p + 5;
    vector<long long> fact(N), invfact(N);
    fact[0] = 1;
    for (int i = 1; i < N; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[N - 1] = modpow(fact[N - 1], MOD - 2);
    for (int i = N - 2; i >= 0; --i)
        invfact[i] = invfact[i + 1] * (i + 1) % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
    };

    // Total number of states: a1 >= r, ai >= 0, sum = s
    // Let t = a1 - r >= 0, sum others + t = s - r
    int S = s - r;
    long long total_states = 0;
    if (S >= 0) {
        for (int t = 0; t <= S; ++t) {
            int rem = S - t;
            total_states = (total_states + C(rem + p - 2, p - 2)) % MOD;
        }
    }

    long long numerator = 0;

    // Iterate over possible Hasan score a1
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        if (rem < 0) break;

        // For each possible maximum score among others m (0..a1)
        for (int m = 0; m <= a1; ++m) {
            long long ways = 0;

            // Count distributions of p-1 players with sum=rem, each in [0, m]
            // Using inclusion-exclusion: number of solutions to sum xi=rem, 0<=xi<=m
            // = sum_{k} (-1)^k * C(p-1, k) * C(rem - k*(m+1) + p-2, p-2)
            for (int k = 0; k <= p - 1; ++k) {
                int val = rem - k * (m + 1);
                if (val < 0) break;
                long long term = C(p - 1, k) * C(val + p - 2, p - 2) % MOD;
                if (k & 1) {
                    ways = (ways - term + MOD) % MOD;
                } else {
                    ways = (ways + term) % MOD;
                }
            }

            if (ways == 0) continue;

            // Count number of players among others with score == m
            // We need expected 1/(k+1) over all states with max=m
            // Instead, we compute sum over states of 1/(k+1).
            // For each possible k>=0, number of states with exactly k players at m:
            // Choose k players at m, others in [0, m-1], sum = rem - k*m
            long long contrib = 0;
            for (int k = 0; k <= p - 1; ++k) {
                int sum_rest = rem - k * m;
                if (sum_rest < 0) break;

                // others' scores in [0, m-1]
                long long cnt_states = 0;
                for (int t = 0; t <= p - 1 - k; ++t) {
                    int val = sum_rest - t * m;
                    if (val < 0) break;
                    long long term = C(p - 1 - k, t) * C(val + p - 2, p - 2) % MOD;
                    if (t & 1) {
                        cnt_states = (cnt_states - term + MOD) % MOD;
                    } else {
                        cnt_states = (cnt_states + term) % MOD;
                    }
                }

                if (cnt_states == 0) continue;

                long long inv = modpow(k + 1, MOD - 2);
                contrib = (contrib + cnt_states * inv) % MOD;
            }

            // If m < a1, Hasan strictly greater than others when max=m
            if (m < a1) {
                numerator = (numerator + ways) % MOD;
            } else { // m == a1
                numerator = (numerator + contrib) % MOD;
            }
        }
    }

    if (total_states == 0) {
        cout << 0 << '\n';
        return 0;
    }

    long long ans = numerator * modpow(total_states % MOD, MOD - 2) % MOD;
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int addmod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}
int submod(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}
int mulmod(long long a, long long b) {
    return int((a * b) % MOD);
}
int modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return int(r);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    if (!(cin >> p >> s >> r)) return 0;

    // Precompute factorials and inverse factorials up to s + p
    int N = s + p + 5;
    vector<int> fact(N), invfact(N);
    fact[0] = 1;
    for (int i = 1; i < N; ++i) fact[i] = mulmod(fact[i - 1], i);
    invfact[N - 1] = modpow(fact[N - 1], MOD - 2);
    for (int i = N - 1; i > 0; --i)
        invfact[i - 1] = mulmod(invfact[i], i);

    auto C = [&](int n, int k) -> int {
        if (k < 0 || k > n) return 0;
        return mulmod(fact[n], mulmod(invfact[k], invfact[n - k]));
    };

    int totalStates = 0;
    int winStates = 0;

    // Iterate over Hasan's score a1
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        // total states for this a1: compositions of rem into p-1 nonnegative parts
        int totalForA1 = C(rem + p - 2, p - 2);
        if (totalForA1 == 0) continue;
        totalStates = addmod(totalStates, totalForA1);

        int sumWinForA1 = 0;

        // Iterate over maximum score m among other players
        for (int m = 0; m <= rem; ++m) {
            // number of states where max other score is exactly m
            // count sequences of length p-1, sum rem, each in [0, m]
            // via inclusion-exclusion
            int cnt = 0;
            int maxK = rem / (m + 1);
            for (int k = 0; k <= maxK; ++k) {
                int sign = (k & 1) ? MOD - 1 : 1;
                int ways = C(p - 1, k);
                int sumLeft = rem - k * (m + 1);
                ways = mulmod(ways, C(sumLeft + p - 2, p - 2));
                cnt = (cnt + mulmod(sign, ways)) % MOD;
            }

            if (cnt == 0) continue;

            if (a1 > m) {
                // Hasan strictly greater than all others
                sumWinForA1 = addmod(sumWinForA1, cnt);
            } else if (a1 == m) {
                // Hasan tied at max; need expected 1/(t+1) where t is number of others with score m
                // For each t>=0, count sequences where exactly t others have score m
                int contrib = 0;
                for (int t = 0; t <= p - 1; ++t) {
                    // choose t players to have score m
                    int chooseT = C(p - 1, t);
                    int rem2 = rem - t * m;
                    if (rem2 < 0) continue;
                    // remaining p-1-t players have scores in [0, m-1], sum rem2
                    int cnt2 = 0;
                    if (m == 0) {
                        // then rem2 must be 0 and all remaining are 0
                        if (rem2 == 0) cnt2 = 1;
                    } else {
                        int maxK2 = rem2 / m;
                        for (int k = 0; k <= maxK2; ++k) {
                            int sign = (k & 1) ? MOD - 1 : 1;
                            int ways = C(p - 1 - t, k);
                            int sumLeft = rem2 - k * m;
                            ways = mulmod(ways, C(sumLeft + (p - 1 - t) - 1, (p - 1 - t) - 1));
                            cnt2 = (cnt2 + mulmod(sign, ways)) % MOD;
                        }
                    }
                    if (cnt2 == 0) continue;
                    int ways = mulmod(chooseT, cnt2);
                    int inv = modpow(t + 1, MOD - 2);
                    contrib = addmod(contrib, mulmod(ways, inv));
                }
                sumWinForA1 = addmod(sumWinForA1, contrib);
            }
        }

        winStates = addmod(winStates, sumWinForA1);
    }

    int invTotal = modpow(totalStates, MOD - 2);
    int ans = mulmod(winStates, invTotal);
    cout << ans << '\n';
    return 0;
}

