    int winContribution = 0;

    // Iterate over Hasan's score a1
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        // number of ways to distribute rem among p-1 players (non-negative)
        int totalForA1 = C(rem + p - 2, p - 2);
        if (totalForA1 == 0) continue;

        // Probability that Hasan wins given a1:
        // sum over k = 0..p-1 (number of other players tied at a1)
        int waysWinGivenA1 = 0;

        for (int k = 0; k <= p - 1; ++k) {
            int others = p - 1;
            int rem2 = rem - 1LL * k * a1;
            if (rem2 < 0) break;

            // choose which k players tie with Hasan
            int chooseTie = C(others, k);

            // count distributions for remaining others-k players
            int playersLeft = others - k;
            int ways = 0;
            if (playersLeft == 0) {
                // all others are tied with Hasan
                if (rem2 == 0) ways = 1;
                else ways = 0;
