                // number of solutions to sum x_i = rem2, 0 <= x_i <= a1-1
                // via inclusion-exclusion
                int maxT = rem2 / a1;
                for (int t = 0; t <= maxT; ++t) {
                    int sign = (t & 1) ? MOD - 1 : 1;
