                    waysPart = mulmod(waysPart, C(rem3 + playersLeft - 1, playersLeft - 1));
                    ways = addmod(ways, mulmod(sign, waysPart));
                }
            }

            if (!ways) continue;

            // probability Hasan wins among (k+1) top scorers: 1/(k+1)
            int inv = modpow(k + 1, MOD - 2);
            int contrib = mulmod(chooseTie, mulmod(ways, inv));
            waysWinGivenA1 = addmod(waysWinGivenA1, contrib);
        }

        winContribution = addmod(winContribution, waysWinGivenA1);
        totalStates = addmod(totalStates, totalForA1);
    }

    if (totalStates == 0) {
        cout << 0 << '\n';
        return 0;
    }

    int invTotal = modpow(totalStates, MOD - 2);
    int ans = mulmod(winContribution, invTotal);
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int addmod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}
int submod(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}
int mulmod(long long a, long long b) {
    return int((a * b) % MOD);
}
int modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return int(r);
}
int invmod(int a) {
    return modpow(a, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    if (!(cin >> p >> s >> r)) return 0;

    // Precompute factorials and inverse factorials up to 5000 + 100
    int N = s + 100;
    vector<int> fact(N + 1), invfact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = mulmod(fact[i - 1], i);
    invfact[N] = invmod(fact[N]);
    for (int i = N; i > 0; --i) invfact[i - 1] = mulmod(invfact[i], i);

    auto C = [&](int n, int k) -> int {
        if (k < 0 || k > n) return 0;
        return mulmod(fact[n], mulmod(invfact[k], invfact[n - k]));
    };

    // Total number of states: compositions of s into p nonnegative parts with a1 >= r
    // Let b1 = a1 - r >= 0, sum b1 + a2 + ... + ap = s - r
    int totalStates = 0;
    if (s >= r) {
        totalStates = C((s - r) + p - 1, p - 1);
    }

    int num = 0; // numerator sum

    // Iterate over Hasan's possible score a1
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1; // sum for other players
        // For each possible maximum score M among other players
        for (int M = 0; M <= rem; ++M) {
            int waysOther = 0;
            // Count number of ways to distribute rem among p-1 players with each <= M
            // Using inclusion-exclusion:
            // ways = sum_{k=0}^{p-1} (-1)^k * C(p-1, k) * C(rem - k*(M+1) + p-2, p-2)
            for (int k = 0; k <= p - 1; ++k) {
                int t = rem - k * (M + 1);
                if (t < 0) break;
                int term = mulmod(C(p - 1, k), C(t + p - 2, p - 2));
                if (k & 1) waysOther = submod(waysOther, term);
                else waysOther = addmod(waysOther, term);
            }
            if (!waysOther) continue;

            if (M > a1) continue; // Hasan cannot win if someone strictly exceeds him

            int contrib;
            if (M < a1) {
                // Hasan strictly greater than all others
                contrib = waysOther;
            } else {
                // M == a1: Hasan tied with some subset of players having score a1
                // Let t = number of other players with score a1 (>=1)
                // For each t, probability Hasan wins is 1/(t+1)
                // Count ways with exactly t players having score a1
                int sumTie = 0;
                for (int t = 1; t <= p - 1; ++t) {
                    int rem2 = rem - t * a1;
                    if (rem2 < 0) break;
                    // remaining p-1-t players have scores in [0, a1-1]
                    int waysRest = 0;
                    if (a1 == 0) {
                        // if a1==0, then rem=0, rem2=0, and t must be p-1; others are all zero
                        if (rem2 == 0 && t == p - 1) {
                            waysRest = 1;
                        } else {
                            waysRest = 0;
                        }
                    } else {
                        for (int k = 0; k <= p - 1 - t; ++k) {
                            int tt = rem2 - k * a1;
                            if (tt < 0) break;
                            int term = mulmod(C(p - 1 - t, k), C(tt + p - 2 - t, p - 2 - t));
                            if (k & 1) waysRest = submod(waysRest, term);
                            else waysRest = addmod(waysRest, term);
                        }
                    }
                    if (!waysRest) continue;
                    int waysChoose = C(p - 1, t);
                    int ways = mulmod(waysChoose, waysRest);
                    int prob = invmod(t + 1);
                    int add = mulmod(ways, prob);
                    sumTie = addmod(sumTie, add);
                }
                contrib = sumTie;
            }
            num = addmod(num, contrib);
        }
    }

    int ans = 0;
    if (totalStates != 0) {
        ans = mulmod(num, invmod(totalStates));
    }
    cout << ans << '\n';
    return 0;
}
